INSERT INTO adoption_reviews (id, request_id, author_role, rating, comment, created_at) VALUES (1, 1, 'ADOPTER', 5, 'O Caramelo chegou vacinado, castrado e com todas as orientações. A Apacri acompanhou a adaptação nas primeiras semanas.', NOW() - INTERVAL '39 days 0 hours');
INSERT INTO adoption_reviews (id, request_id, author_role, rating, comment, created_at) VALUES (2, 1, 'OWNER', 5, 'A Mariana preparou a casa antes de buscar o Caramelo e manda fotos até hoje. Adotante exemplar!', NOW() - INTERVAL '38 days 0 hours');
INSERT INTO adoption_reviews (id, request_id, author_role, rating, comment, created_at) VALUES (3, 2, 'ADOPTER', 4, 'Processo tranquilo e bem explicado. Só achei a entrevista um pouco demorada.', NOW() - INTERVAL '58 days 0 hours');
INSERT INTO adoption_reviews (id, request_id, author_role, rating, comment, created_at) VALUES (4, 3, 'OWNER', 4, 'A Fernanda tentou de verdade a adaptação e devolveu o Laranja com cuidado, avisando com antecedência.', NOW() - INTERVAL '9 days 0 hours');
INSERT INTO adoption_reviews (id, request_id, author_role, rating, comment, created_at) VALUES (5, 4, 'ADOPTER', 5, 'A Acapra foi atenciosa do primeiro contato até a entrega. A Luna é a melhor companheira de corrida!', NOW() - INTERVAL '13 days 0 hours');
